<script setup>
import {computed,ref} from 'vue'
import {Activity,AlertTriangle,ArrowDownToLine,ArrowUpFromLine,BarChart3,Bell,Boxes,Building2,ChevronDown,CircleUserRound,ClipboardList,FileText,LayoutDashboard,LogIn,LogOut,Menu,Package,Plus,Search,Settings,ShoppingBag,Truck,UserPlus,X} from 'lucide-vue-next'
const authMode=ref('login'),currentUser=ref(null),businesses=ref([]),activeBusinessId=ref(null),activePage=ref('Dashboard'),mobileOpen=ref(false),showWorkspaceMenu=ref(false),showCreateBusiness=ref(false),notice=ref(''),search=ref(''),products=ref([]),movements=ref([]),suppliers=ref([])
const demo={email:'jamie@stockpilot.demo',password:'demo1234',name:'Jamie Mejia'}
const nav=[['Dashboard',LayoutDashboard],['Products',Package],['Inventory',ClipboardList],['Stock Movements',Activity],['Suppliers',Truck],['Reports',BarChart3],['Activity',FileText]]
const activeBusiness=computed(()=>businesses.value.find(b=>b.id===activeBusinessId.value)||null)
const bp=computed(()=>products.value.filter(p=>p.business_id===activeBusinessId.value)),bm=computed(()=>movements.value.filter(m=>m.business_id===activeBusinessId.value)),bs=computed(()=>suppliers.value.filter(s=>s.business_id===activeBusinessId.value))
const status=p=>p.qty===0?'Out of stock':p.qty<=p.low?'Low stock':'Healthy', totalUnits=computed(()=>bp.value.reduce((a,p)=>a+p.qty,0)),value=computed(()=>bp.value.reduce((a,p)=>a+p.qty*p.cost,0)),attention=computed(()=>bp.value.filter(p=>status(p)!=='Healthy').length)
const money=v=>new Intl.NumberFormat('en-PH',{style:'currency',currency:activeBusiness.value?.currency||'PHP',maximumFractionDigits:0}).format(v)
function flash(t){notice.value=t;setTimeout(()=>notice.value='',2800)}
function login(e){const f=new FormData(e.target);if(f.get('email')!==demo.email||f.get('password')!==demo.password)return flash('Use the preview credentials shown below.');currentUser.value={name:demo.name,email:demo.email};const b={id:1,name:'Mejia Moto Supply',type:'Motorcycle Parts',size:'Small (1–5 people)',currency:'PHP',trackSuppliers:true,lowStock:true,role:'OWNER'};businesses.value=[b];activeBusinessId.value=1;seedBusiness(b);flash('Welcome back, Jamie.')}
function register(e){const f=new FormData(e.target);currentUser.value={name:String(f.get('name')),email:String(f.get('email'))};businesses.value=[];activeBusinessId.value=null}
function seedBusiness(b){const sets={
'Retail Store':[['Coca-Cola 1.5L','Beverages',35,12,55],['Instant Noodles','Food',58,20,12],['Laundry Soap','Household',9,10,24]],
'Motorcycle Parts':[['Brake Pad Set','Parts',18,10,280],['Engine Oil 1L','Lubricants',7,12,205],['Spark Plug CR8E','Parts',42,15,95],['Chain Cleaner 500ml','Maintenance',0,6,175]],
'Food Business':[['Rice 25kg','Ingredients',8,3,1250],['Cooking Oil 5L','Ingredients',4,5,520],['Takeout Box','Packaging',120,50,6]],
'Online Seller':[['Classic T-Shirt','Apparel',24,8,180],['Mailer Pouch','Packaging',70,20,5],['Canvas Tote','Accessories',6,8,120]],
'Small Warehouse':[['Storage Box L','Storage',26,10,310],['Packing Tape','Supplies',44,15,45],['Bubble Wrap Roll','Supplies',9,10,190]],
'Other':[['Sample Product','General',20,5,100]]};
(sets[b.type]||sets.Other).forEach((x,i)=>products.value.push({id:Date.now()+i,business_id:b.id,name:x[0],category:x[1],sku:`${b.id}-${String(i+1).padStart(3,'0')}`,qty:x[2],low:x[3],cost:x[4]}));if(b.trackSuppliers){suppliers.value.push({id:Date.now(),business_id:b.id,name:b.type==='Motorcycle Parts'?'Davao Moto Supply':'Primary Supplier',contact:'supplier@example.com',items:2})}movements.value.push({id:Date.now(),business_id:b.id,type:'Stock In',item:(sets[b.type]||sets.Other)[0][0],qty:'+12',user:currentUser.value.name,time:'Today'})}
function createBusiness(e){const f=new FormData(e.target),id=Date.now();const b={id,name:String(f.get('name')),type:String(f.get('type')),size:String(f.get('size')),currency:String(f.get('currency')),trackSuppliers:f.get('suppliers')==='yes',lowStock:f.get('alerts')==='yes',role:'OWNER'};businesses.value.push(b);activeBusinessId.value=id;seedBusiness(b);showCreateBusiness.value=false;activePage.value='Dashboard';flash(`${b.name} workspace created and tailored for ${b.type}.`)}
function selectBusiness(id){activeBusinessId.value=id;showWorkspaceMenu.value=false;activePage.value='Dashboard'}
function go(page){activePage.value=page;mobileOpen.value=false;search.value=''}
function logout(){currentUser.value=null;businesses.value=[];activeBusinessId.value=null;products.value=[];movements.value=[];suppliers.value=[];activePage.value='Dashboard';authMode.value='login'}
function addProduct(){if(activePage.value!=='Products')activePage.value='Products';const n=prompt('Product name');if(!n)return;products.value.push({id:Date.now(),business_id:activeBusinessId.value,name:n,category:'General',sku:`NEW-${bp.value.length+1}`,qty:0,low:5,cost:0});flash(`${n} added.`)}
function stock(p,delta){p.qty=Math.max(0,p.qty+delta);movements.value.unshift({id:Date.now(),business_id:activeBusinessId.value,type:delta>0?'Stock In':'Stock Out',item:p.name,qty:(delta>0?'+':'')+delta,user:currentUser.value.name,time:'Just now'});flash(`${p.name} stock updated.`)}
const filtered=computed(()=>{const q=search.value.toLowerCase();return bp.value.filter(p=>!q||`${p.name} ${p.sku} ${p.category}`.toLowerCase().includes(q))})
</script>
<template><Transition name="page" mode="out-in">
<div v-if="!currentUser" class="auth-page" key="auth"><section class="auth-brand"><div class="auth-brand-copy"><div class="auth-logo"><Boxes :size="28"/></div><span class="eyebrow">Mejia Software</span><h1>StockPilot</h1><p>Inventory that adapts to the way your business actually works.</p><div class="visual-flow"><div class="flow-track"><span/></div><div class="flow-node node-user"><CircleUserRound :size="19"/><small>Account</small></div><div class="flow-node node-business"><Building2 :size="19"/><small>Business</small></div><div class="flow-node node-stock"><Package :size="19"/><small>Stock</small></div></div><div class="auth-feature"><Building2 :size="18"/><span><strong>Built around your business.</strong><small>Tell StockPilot what you run and the workspace adapts.</small></span></div><div class="auth-feature"><Activity :size="18"/><span><strong>One account. Separate workspaces.</strong><small>Products, suppliers and activity stay with the right business.</small></span></div></div></section><section class="auth-panel"><div class="auth-card"><div class="auth-tabs"><button :class="{active:authMode==='login'}" @click="authMode='login'">Log in</button><button :class="{active:authMode==='register'}" @click="authMode='register'">Register</button><span class="tab-slider" :class="{'tab-slider--register':authMode==='register'}"/></div><Transition name="auth-swap" mode="out-in"><div :key="authMode" class="auth-form-view"><template v-if="authMode==='login'"><span class="eyebrow">Welcome back</span><h2>Log in to StockPilot</h2><p>Open your business workspaces and continue where you left off.</p><form class="auth-form" @submit.prevent="login"><label>Email<input name="email" type="email" required/></label><label>Password<input name="password" type="password" required/></label><button class="primary-button auth-submit"><LogIn :size="17"/>Log in</button></form><div class="demo-credentials"><strong>Preview account</strong><span>jamie@stockpilot.demo</span><span>Password: demo1234</span></div></template><template v-else><span class="eyebrow">Start free</span><h2>Create your account</h2><p>Next, we'll ask a few questions about your business and build the workspace around it.</p><form class="auth-form" @submit.prevent="register"><label>Full name<input name="name" required/></label><label>Email<input name="email" type="email" required/></label><label>Password<input name="password" type="password" minlength="8" required/></label><button class="primary-button auth-submit"><UserPlus :size="17"/>Continue to business setup</button></form></template></div></Transition></div></section></div>
<div v-else-if="!activeBusiness" class="onboarding-page" key="setup"><div class="onboarding-card onboarding-wide"><div class="modal-icon"><Building2 :size="24"/></div><span class="eyebrow">Workspace setup · about 1 minute</span><h1>Tell us about your business</h1><p>StockPilot uses these answers to tailor your starting dashboard, sample inventory and tools. You can change them later.</p><form class="auth-form setup-grid" @submit.prevent="createBusiness"><label class="full">Business name<input name="name" required placeholder="e.g. Mejia Hardware"/></label><label>What kind of business?<select name="type"><option>Retail Store</option><option>Motorcycle Parts</option><option>Food Business</option><option>Online Seller</option><option>Small Warehouse</option><option>Other</option></select></label><label>Team size<select name="size"><option>Just me</option><option>Small (1–5 people)</option><option>Growing (6–20 people)</option><option>20+ people</option></select></label><label>Track suppliers?<select name="suppliers"><option value="yes">Yes, I buy from suppliers</option><option value="no">Not right now</option></select></label><label>Low-stock alerts?<select name="alerts"><option value="yes">Yes, warn me early</option><option value="no">No alerts for now</option></select></label><label>Currency<select name="currency"><option value="PHP">PHP — Philippine Peso</option><option value="USD">USD — US Dollar</option></select></label><label>How do you sell?<select name="sales"><option>Physical store</option><option>Online</option><option>Both online and physical</option><option>Internal inventory only</option></select></label><button class="primary-button auth-submit full">Build my StockPilot workspace</button></form><button class="logout-link" @click="logout"><LogOut :size="15"/>Use another account</button></div></div>
<div v-else class="app-shell" key="app"><aside class="sidebar" :class="{'sidebar--open':mobileOpen}"><div class="brand-row"><div class="brand-mark"><Boxes :size="20"/></div><div><div class="brand-name">StockPilot</div><div class="brand-byline">by Mejia Software</div></div></div><div class="workspace-wrap"><button class="workspace-card" @click="showWorkspaceMenu=!showWorkspaceMenu"><div class="workspace-icon"><ShoppingBag :size="17"/></div><div class="workspace-copy"><strong>{{activeBusiness.name}}</strong><span>{{activeBusiness.type}}</span></div><ChevronDown :size="16"/></button><div v-if="showWorkspaceMenu" class="workspace-menu"><button v-for="b in businesses" :key="b.id" class="workspace-option" @click="selectBusiness(b.id)"><Building2 :size="16"/><span><strong>{{b.name}}</strong><small>{{b.type}}</small></span></button><button class="workspace-create" @click="showWorkspaceMenu=false;showCreateBusiness=true"><Plus :size="16"/>Create another business</button></div></div><nav class="nav-list"><button v-for="[label,Icon] in nav" :key="label" class="nav-item sidebar-link" :class="{'nav-item--active':activePage===label}" @click="go(label)"><component :is="Icon" :size="18"/>{{label}}</button></nav><div class="sidebar-bottom"><button class="nav-item sidebar-link" :class="{'nav-item--active':activePage==='Settings'}" @click="go('Settings')"><Settings :size="18"/>Settings</button><button class="nav-item logout-button" @click="logout"><LogOut :size="18"/>Log out</button><div class="user-row"><div class="avatar">{{currentUser.name.slice(0,2).toUpperCase()}}</div><div><strong>{{currentUser.name}}</strong><span>{{activeBusiness.role}}</span></div></div></div></aside><main class="main-area"><header class="topbar"><button class="menu-button" @click="mobileOpen=true"><Menu/></button><div class="global-search"><Search :size="18"/><input v-model="search" :placeholder="`Search ${activePage.toLowerCase()}...`"/></div><div class="topbar-actions"><span class="tenant-pill"><Building2 :size="13"/>{{activeBusiness.name}}</span><button class="icon-button"><Bell :size="19"/></button></div></header><div class="content-wrap"><section class="hero-row"><div><span class="eyebrow">{{activeBusiness.type}} · {{activeBusiness.name}}</span><h1>{{activePage}}</h1><p v-if="activePage==='Dashboard'">A workspace tailored for your {{activeBusiness.type.toLowerCase()}} business.</p></div><button v-if="['Dashboard','Products','Inventory'].includes(activePage)" class="primary-button" @click="addProduct"><Plus :size="17"/>Add product</button></section>
<template v-if="activePage==='Dashboard'"><section class="metric-grid"><article class="metric-card"><Package/><span class="metric-label">Products</span><strong>{{bp.length}}</strong><small>{{activeBusiness.type}}</small></article><article class="metric-card"><Boxes/><span class="metric-label">Units on hand</span><strong>{{totalUnits}}</strong></article><article class="metric-card"><BarChart3/><span class="metric-label">Inventory value</span><strong>{{money(value)}}</strong></article><article class="metric-card"><AlertTriangle/><span class="metric-label">Needs attention</span><strong>{{attention}}</strong></article></section><div class="dashboard-grid"><section class="panel"><div class="panel-header"><h2>Inventory snapshot</h2><button class="text-button" @click="go('Inventory')">View inventory</button></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Stock</th><th>Status</th></tr></thead><tbody><tr v-for="p in bp.slice(0,5)" :key="p.id"><td><strong>{{p.name}}</strong></td><td>{{p.category}}</td><td>{{p.qty}}</td><td><span class="status-badge" :class="'status-'+status(p).toLowerCase().replaceAll(' ','-')">{{status(p)}}</span></td></tr></tbody></table></div></section><section class="panel"><div class="panel-header"><h2>Recent movements</h2></div><div class="movement-list"><div v-for="m in bm.slice(0,5)" :key="m.id" class="movement-row"><div class="movement-copy"><strong>{{m.item}}</strong><span>{{m.type}} · {{m.user}}</span></div><b>{{m.qty}}</b></div></div></section></div></template>
<template v-else-if="activePage==='Products'"><section class="panel"><div class="panel-header"><h2>Product catalog</h2><span class="muted">{{filtered.length}} products</span></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Cost</th><th>Stock</th></tr></thead><tbody><tr v-for="p in filtered" :key="p.id"><td><strong>{{p.name}}</strong></td><td class="mono">{{p.sku}}</td><td>{{p.category}}</td><td>{{money(p.cost)}}</td><td>{{p.qty}}</td></tr></tbody></table></div></section></template>
<template v-else-if="activePage==='Inventory'"><section class="panel"><div class="panel-header"><h2>Inventory control</h2><span class="muted">Use + / − to record stock movement</span></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>On hand</th><th>Low at</th><th>Status</th><th>Adjust</th></tr></thead><tbody><tr v-for="p in filtered" :key="p.id"><td><strong>{{p.name}}</strong></td><td>{{p.qty}}</td><td>{{p.low}}</td><td>{{status(p)}}</td><td><button class="mini-btn" @click="stock(p,-1)">−</button><button class="mini-btn" @click="stock(p,1)">+</button></td></tr></tbody></table></div></section></template>
<template v-else-if="activePage==='Stock Movements'"><section class="panel"><div class="panel-header"><h2>Stock movement history</h2></div><div class="table-wrap"><table><thead><tr><th>Type</th><th>Product</th><th>Quantity</th><th>User</th><th>Time</th></tr></thead><tbody><tr v-for="m in bm" :key="m.id"><td>{{m.type}}</td><td>{{m.item}}</td><td><strong>{{m.qty}}</strong></td><td>{{m.user}}</td><td>{{m.time}}</td></tr></tbody></table></div></section></template>
<template v-else-if="activePage==='Suppliers'"><section class="panel"><div class="panel-header"><h2>Suppliers</h2><button class="primary-button" @click="flash('Supplier form is ready for backend persistence next.')"><Plus :size="16"/>Add supplier</button></div><div v-if="activeBusiness.trackSuppliers" class="card-list"><article v-for="s in bs" :key="s.id" class="data-card"><Truck/><div><strong>{{s.name}}</strong><span>{{s.contact}} · {{s.items}} linked products</span></div></article></div><div v-else class="empty-state"><Truck :size="34"/><h2>Supplier tracking is off</h2><p>Enable it in Settings whenever this business starts buying from suppliers.</p></div></section></template>
<template v-else-if="activePage==='Reports'"><section class="metric-grid"><article class="metric-card"><BarChart3/><span class="metric-label">Stock value</span><strong>{{money(value)}}</strong></article><article class="metric-card"><Package/><span class="metric-label">Products</span><strong>{{bp.length}}</strong></article><article class="metric-card"><ArrowDownToLine/><span class="metric-label">Movements</span><strong>{{bm.length}}</strong></article><article class="metric-card"><AlertTriangle/><span class="metric-label">Attention</span><strong>{{attention}}</strong></article></section><div class="panel report-panel"><h2>{{activeBusiness.name}} inventory summary</h2><p>Your report automatically uses this workspace only. Export/PDF will be connected when the backend is added.</p></div></template>
<template v-else-if="activePage==='Activity'"><section class="panel"><div class="panel-header"><h2>Business activity</h2></div><div class="activity-feed"><div v-for="m in bm" :key="m.id" class="activity-item"><Activity/><div><strong>{{m.user}} recorded {{m.type.toLowerCase()}}</strong><span>{{m.item}} · {{m.qty}} · {{m.time}}</span></div></div></div></section></template>
<template v-else-if="activePage==='Settings'"><section class="panel settings-panel"><h2>Business settings</h2><p>These choices came from onboarding and control how StockPilot is tailored.</p><div class="settings-grid"><label>Business name<input v-model="activeBusiness.name"/></label><label>Business type<input :value="activeBusiness.type" disabled/></label><label>Team size<input :value="activeBusiness.size" disabled/></label><label>Currency<input :value="activeBusiness.currency" disabled/></label><label class="toggle-row"><input v-model="activeBusiness.trackSuppliers" type="checkbox"/> Track suppliers</label><label class="toggle-row"><input v-model="activeBusiness.lowStock" type="checkbox"/> Low-stock alerts</label></div></section></template>
</div></main><div v-if="mobileOpen" class="mobile-scrim mobile-scrim--open" @click="mobileOpen=false"/></div></Transition>
<div v-if="showCreateBusiness" class="modal-backdrop"><div class="modal-card"><button class="modal-close" @click="showCreateBusiness=false"><X/></button><h2>Create another business</h2><p>Each business gets its own isolated inventory.</p><form class="auth-form" @submit.prevent="createBusiness"><label>Business name<input name="name" required/></label><label>Type<select name="type"><option>Retail Store</option><option>Motorcycle Parts</option><option>Food Business</option><option>Online Seller</option><option>Small Warehouse</option><option>Other</option></select></label><input type="hidden" name="size" value="Just me"/><input type="hidden" name="currency" value="PHP"/><input type="hidden" name="suppliers" value="yes"/><input type="hidden" name="alerts" value="yes"/><button class="primary-button auth-submit">Create workspace</button></form></div></div>
<Transition name="toast"><div v-if="notice" class="toast"><span>{{notice}}</span><button @click="notice=''"><X :size="16"/></button></div></Transition></template>